fn native_environment(mut read: impl FnMut(&str) -> Option<OsString>) -> BTreeMap<OsString, OsString> {
    [
            "HTTP_PROXY",
            "HTTPS_PROXY",
            "ALL_PROXY",
            "NO_PROXY",
            "http_proxy",
            "https_proxy",
            "all_proxy",
            "no_proxy",
            "SSL_CERT_FILE",
            "SSL_CERT_DIR",
            "XDG_RUNTIME_DIR",
            "DBUS_SESSION_BUS_ADDRESS",
            "XDG_CONFIG_HOME",
            "XDG_DATA_HOME",
            "XDG_CACHE_HOME",
            "LANG",
            "LC_ALL",
        ]
        .into_iter()
        .filter_map(|name| read(name).map(|value| (OsString::from(name), value)))
        .collect()
}

